import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, Chrome, UserPlus } from 'lucide-react';

const Home = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  // Your chosen background image from Pinterest
  const bgImage = "https://i.pinimg.com/1200x/6c/70/eb/6c70ebe9c83a988ab24e94c0c222cd1c.jpg";

  const handleGoogleSignIn = () => {
    /* global google */
    try {
      if (window.google) {
        google.accounts.id.initialize({
          client_id: "YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com",
          callback: (response) => {
            console.log("Login Success:", response.credential);
            navigate('/admin'); 
          },
        });
        google.accounts.id.prompt(); 
      } else {
        console.error("Google script not loaded. Make sure you added it to index.html");
      }
    } catch (error) {
      console.error("Google Sign-In Error:", error);
    }
  };

  const handleLogin = (e) => {
    e.preventDefault();
    console.log("Redirecting to Admin....");
    // This connects the Login button to the Admin Dashboard
    navigate('/admin'); 
  };

  return (
    <div 
      className="min-h-screen flex flex-col font-sans relative bg-cover bg-center bg-no-repeat"
      style={{ 
        backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)), url(${bgImage})` 
      }}
    >
      
      {/* Top Right Register Button */}
      <div className="absolute top-6 right-8 z-20">
        <button 
          onClick={() => navigate('/register')}
          className="flex items-center gap-2 bg-white/90 backdrop-blur-sm text-[#7c5dfa] border border-[#7c5dfa] px-6 py-2.5 rounded-full font-bold hover:bg-[#7c5dfa] hover:text-white transition-all shadow-xl active:scale-95"
        >
          <UserPlus size={18} />
          Register
        </button>
      </div>

      <div className="flex-grow flex items-center justify-center p-4">
        {/* Login Card with Glassmorphism effect */}
        <div className="bg-white/95 backdrop-blur-md p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md border border-white/20 animate-in fade-in zoom-in duration-500">
          
          <div className="text-center mb-10">
            <div className="inline-block bg-purple-100 p-4 rounded-2xl mb-4 shadow-inner">
              <div className="bg-[#7c5dfa] w-12 h-12 rounded-xl flex items-center justify-center shadow-lg">
                <Lock className="text-white" size={24} />
              </div>
            </div>
            <h1 className="text-3xl font-black text-gray-800 tracking-tight">Talent Pool</h1>
            <p className="text-gray-500 text-sm mt-2 font-medium">Enter your credentials to manage the pool</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Email Address</label>
              <div className="relative group">
                <Mail className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-[#7c5dfa] transition-colors" size={20} />
                <input 
                  type="email" 
                  placeholder="admin@company.com"
                  className="w-full pl-12 pr-4 py-3.5 bg-gray-50/50 border border-gray-200 rounded-2xl focus:ring-4 focus:ring-purple-100 focus:bg-white focus:border-[#7c5dfa] outline-none transition-all"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2 ml-1">Password</label>
              <div className="relative group">
                <Lock className="absolute left-4 top-3.5 text-gray-400 group-focus-within:text-[#7c5dfa] transition-colors" size={20} />
                <input 
                  type="password" 
                  placeholder="••••••••"
                  className="w-full pl-12 pr-4 py-3.5 bg-gray-50/50 border border-gray-200 rounded-2xl focus:ring-4 focus:ring-purple-100 focus:bg-white focus:border-[#7c5dfa] outline-none transition-all"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </div>
            </div>

            <button 
              type="submit"
              className="w-full bg-[#7c5dfa] hover:bg-[#6a4dec] text-white font-black py-4 rounded-2xl shadow-xl shadow-purple-200 transition-all transform active:scale-[0.97]"
            >
              LOGIN TO DASHBOARD
            </button>
          </form>

          <div className="flex items-center my-8">
            <div className="flex-grow border-t border-gray-100"></div>
            <span className="px-4 text-gray-300 text-[10px] font-black uppercase tracking-[0.2em]">Social Access</span>
            <div className="flex-grow border-t border-gray-100"></div>
          </div>

          <button 
            type="button"
            onClick={handleGoogleSignIn} 
            className="w-full flex items-center justify-center gap-3 border border-gray-200 py-3.5 rounded-2xl hover:bg-gray-50 hover:border-gray-300 transition-all text-gray-600 font-bold bg-white shadow-sm"
          >
            <Chrome size={20} className="text-red-500" />
            Continue with Google
          </button>
        </div>
      </div>
    </div>
  );
};

export default Home;
